/* All content is already in the HTML (generated by build.js for each language).
   This script only brings it to life: intro, menu, scroll effects, player, gallery, cursor. */
(() => {
  "use strict";

  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const root = document.documentElement;
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const isDesktop = () => innerWidth > 960;
  const lang = I18N[root.lang] ? root.lang : "en";
  const ROOT = window.ROOT || "";

  const t = (k) => (I18N[lang] && I18N[lang][k]) ?? I18N.en[k] ?? "";
  const pad = (n) => String(n).padStart(2, "0");
  const clock = (s) => `${pad(Math.floor(s / 60))}:${pad(Math.floor(s % 60))}`;
  const store = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { /* storage unavailable */ } };
  const read = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };

  /* ======================================================================
     Language links — remember the choice and stay in the same section
     ====================================================================== */
  // Opened straight from disk (file://) there is no web server to turn "en/" into "en/index.html"
  const LOCAL = location.protocol === "file:";
  const page = (href) => (LOCAL && href.endsWith("/") ? href + "index.html" : href);
  $$("a[data-lang]").forEach((a) => { a.href = page(a.getAttribute("href")); });

  function currentSection() {
    let id = "";
    $$("main > section[id]").forEach((s) => { if (s.getBoundingClientRect().top < innerHeight * 0.4) id = s.id; });
    return id && id !== "top" ? "#" + id : "";
  }
  $$("a[data-lang]").forEach((a) => a.addEventListener("click", (e) => {
    store("lang", a.dataset.lang);
    if (a.dataset.lang === lang) { e.preventDefault(); closeMenu(); return; }
    try { sessionStorage.setItem("intro", "1"); } catch (err) { /* ignore */ }
    a.href = a.getAttribute("href").split("#")[0] + currentSection();
  }));

  // Croatian home page: offer EN/DE once to visitors whose browser speaks another language
  if (lang === "hr" && !read("lang")) {
    const nav = (navigator.language || "").slice(0, 2).toLowerCase();
    if (!["hr", "bs", "sr", "sl", "me"].includes(nav)) {
      const target = nav === "de" ? "de" : "en";
      const note = $("#langnote"), link = $("#langnoteLink");
      link.textContent = I18N[target].langnote;
      link.href = page(`${target}/`);
      link.setAttribute("hreflang", target);
      link.addEventListener("click", () => { store("lang", target); link.href = page(`${target}/`) + currentSection(); });
      $("#langnoteClose").addEventListener("click", () => { note.classList.remove("show"); store("lang", "hr"); });
      note.hidden = false;
      setTimeout(() => note.classList.add("show"), 2600);
    }
  }

  /* ======================================================================
     Intro — A tuned from 415 to 442 Hz while one bow stroke crosses the screen
     ====================================================================== */
  function runIntro(done) {
    if (root.classList.contains("no-intro")) { done(); return; }
    try { sessionStorage.setItem("intro", "1"); } catch (e) { /* ignore */ }
    const hz = $("#hz"), start = performance.now(), D = 1500;
    const step = (now) => {
      const p = Math.min(1, (now - start) / D);
      hz.textContent = Math.round(415 + 27 * (1 - Math.pow(1 - p, 3)));
      if (p < 1) requestAnimationFrame(step);
      else setTimeout(() => { $("#intro").classList.add("done"); setTimeout(done, 250); }, 250);
    };
    requestAnimationFrame(step);
  }

  /* split the hero name into letters for the entrance (the h1 keeps a readable label) */
  const h1 = $(".hero__name");
  h1.setAttribute("aria-label", h1.textContent.replace(/\s+/g, " ").trim());
  $$("[data-split]").forEach((el) => {
    const delay = el.classList.contains("hero__word--it") ? 0.25 : 0;
    el.innerHTML = [...el.textContent].map((c, i) =>
      `<span class="ch" aria-hidden="true"><span style="transition-delay:${(0.05 + i * 0.045 + delay).toFixed(3)}s">${c}</span></span>`).join("");
  });

  /* ======================================================================
     Header & programme menu
     ====================================================================== */
  const head = $("#head");
  const navLinks = $$(".head__nav a");
  const targets = navLinks.map((a) => $(a.getAttribute("href")));
  let lastY = 0;

  function openMenu() { document.body.classList.add("menu-open"); $("#menuBtn").setAttribute("aria-expanded", "true"); $("#programme").setAttribute("aria-hidden", "false"); }
  function closeMenu() { document.body.classList.remove("menu-open"); $("#menuBtn").setAttribute("aria-expanded", "false"); $("#programme").setAttribute("aria-hidden", "true"); }
  $("#menuBtn").addEventListener("click", () => document.body.classList.contains("menu-open") ? closeMenu() : openMenu());
  $$("#programme a[href^='#']").forEach((a) => a.addEventListener("click", closeMenu));

  /* ======================================================================
     Statement — words light up as you read
     ====================================================================== */
  const statement = $("#statementText");
  const words = $$(".w", statement);
  function updateStatement() {
    const r = statement.getBoundingClientRect();
    const p = (innerHeight * 0.82 - r.top) / (r.height + innerHeight * 0.25);
    const lit = Math.round(Math.max(0, Math.min(1, p)) * words.length);
    words.forEach((w, i) => w.classList.toggle("on", i < lit));
  }

  /* ======================================================================
     Timeline (horizontal, pinned on desktop)
     ====================================================================== */
  const tlWrap = $("#timeline"), tlTrack = $("#timelineTrack");
  const tlItems = $$(".tl", tlTrack);
  function sizeTimeline() {
    if (!isDesktop()) { tlWrap.style.height = ""; tlTrack.style.transform = ""; return; }
    tlWrap.style.height = `${innerHeight + Math.max(0, tlTrack.scrollWidth - innerWidth)}px`;
  }
  function updateTimeline() {
    if (isDesktop()) {
      const r = tlWrap.getBoundingClientRect();
      const dist = tlTrack.scrollWidth - innerWidth;
      const p = Math.max(0, Math.min(1, -r.top / Math.max(1, r.height - innerHeight)));
      tlTrack.style.transform = `translate3d(${(-p * dist).toFixed(1)}px,0,0)`;
      $("#timelineProgress").style.transform = `scaleX(${p})`;
      tlItems.forEach((el) => el.classList.toggle("on", el.getBoundingClientRect().left < innerWidth * 0.62 && r.top < innerHeight * 0.5));
    } else {
      tlItems.forEach((el) => el.classList.toggle("on", el.getBoundingClientRect().top < innerHeight * 0.72));
    }
  }

  /* ======================================================================
     Biography — full text is in the HTML, folded until opened
     ====================================================================== */
  const bioToggle = $("#bioToggle"), bioFull = $("#bioFull");
  bioFull.hidden = true;
  bioToggle.addEventListener("click", () => {
    const open = bioToggle.getAttribute("aria-expanded") !== "true";
    bioToggle.setAttribute("aria-expanded", String(open));
    bioFull.hidden = !open;
    $(".bio__toggle-label").textContent = t(open ? "bio.close" : "bio.read");
    requestAnimationFrame(sizeTimeline);
  });

  /* ======================================================================
     Concerts — the page may be older than today: move passed dates to the archive
     ====================================================================== */
  (function concerts() {
    const today = new Date();
    const iso = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
    const up = $("#upcoming"), past = $("#past");
    const moved = $$("li[data-date]", up).filter((li) => li.dataset.date < iso);
    if (!moved.length) return;
    moved.reverse().forEach((li) => past.prepend(li));
    $(".concerts__past").hidden = false;
    if (!$("li[data-date]", up)) {
      up.innerHTML = `<li class="empty">${t("concerts.empty")}<br><a href="#coda">${t("concerts.booking")} →</a></li>`;
    }
  })();

  /* ======================================================================
     III. Audio — circular waveform ("the disc")
     ====================================================================== */
  const Disc = (() => {
    const audio = $("#player");
    const canvas = $("#discCanvas");
    const ctx = canvas.getContext("2d");
    const items = $$("#tracklist li");
    let cur = 0, loaded = -1, raf = 0, size = 0, dpr = 1;

    function resize() {
      dpr = Math.min(2, devicePixelRatio || 1);
      size = canvas.clientWidth;
      canvas.width = canvas.height = Math.round(size * dpr);
      draw(performance.now());
    }

    function draw(now) {
      const peaks = (PEAKS[TRACKS[cur].id] || { peaks: [] }).peaks;
      const N = peaks.length || 120;
      const progress = loaded === cur && audio.duration ? audio.currentTime / audio.duration : 0;
      const playing = loaded === cur && !audio.paused;
      const s = size * dpr, c = s / 2;
      const r0 = s * 0.285, maxL = s * 0.17, ring = r0 + maxL + 18 * dpr;
      ctx.clearRect(0, 0, s, s);
      ctx.lineCap = "round";

      // outer measuring ring with 60 ticks
      ctx.strokeStyle = "rgba(236,233,226,.14)";
      ctx.lineWidth = dpr;
      ctx.beginPath(); ctx.arc(c, c, ring, 0, Math.PI * 2); ctx.stroke();
      for (let i = 0; i < 60; i++) {
        const a = -Math.PI / 2 + (i / 60) * Math.PI * 2, L = (i % 5 ? 4 : 9) * dpr;
        ctx.beginPath();
        ctx.moveTo(c + Math.cos(a) * ring, c + Math.sin(a) * ring);
        ctx.lineTo(c + Math.cos(a) * (ring + L), c + Math.sin(a) * (ring + L));
        ctx.stroke();
      }

      // waveform bars
      ctx.lineWidth = Math.max(1.2 * dpr, (2 * Math.PI * r0 / N) * 0.42);
      for (let i = 0; i < N; i++) {
        const a = -Math.PI / 2 + (i / N) * Math.PI * 2;
        let v = peaks[i] ?? 0.3;
        if (playing && !reduce) v *= 1 + 0.07 * Math.sin(now / 160 + i * 0.7);
        const r1 = r0 + 6 * dpr, L = 3 * dpr + v * maxL;
        ctx.strokeStyle = i / N < progress ? "#eaae6e" : "rgba(236,233,226,.26)";
        ctx.beginPath();
        ctx.moveTo(c + Math.cos(a) * r1, c + Math.sin(a) * r1);
        ctx.lineTo(c + Math.cos(a) * (r1 + L), c + Math.sin(a) * (r1 + L));
        ctx.stroke();
      }

      // playhead
      if (loaded === cur) {
        const a = -Math.PI / 2 + progress * Math.PI * 2;
        ctx.fillStyle = "#eaae6e";
        ctx.beginPath(); ctx.arc(c + Math.cos(a) * ring, c + Math.sin(a) * ring, 4.5 * dpr, 0, Math.PI * 2); ctx.fill();
      }
      raf = playing ? requestAnimationFrame(draw) : 0;
    }

    function select(i) {
      cur = i;
      items.forEach((li, k) => li.classList.toggle("cur", k === i));
      refreshText();
      draw(performance.now());
    }
    const play = () => audio.play().catch(() => {});
    function load() { loaded = cur; audio.src = `${ROOT}assets/audio/${TRACKS[cur].id}.mp3`; }
    function toggle(i = cur) {
      if (i !== cur) select(i);
      if (loaded !== cur) { load(); play(); }
      else if (audio.paused) play(); else audio.pause();
    }
    function refreshText() {
      const tr = TRACKS[cur];
      const playing = loaded === cur && !audio.paused;
      $("#discComposer").textContent = tr.composer;
      $("#discState").textContent = loaded === cur ? (playing ? t("audio.now") : tr.work) : t("audio.ready");
      const total = PEAKS[tr.id] ? PEAKS[tr.id].duration : 0;
      $("#discTime").textContent = `${clock(loaded === cur ? audio.currentTime : 0)} / ${clock(total)}`;
      $("#discBtn").setAttribute("aria-label", `${t(playing ? "audio.pause" : "audio.play")}: ${tr.composer}, ${tr.work}`);
      $(".audio").classList.toggle("playing", playing);
    }

    items.forEach((li, i) => $("button", li).addEventListener("click", () => toggle(i)));
    $("#discBtn").addEventListener("click", () => toggle());
    canvas.addEventListener("pointerdown", (e) => {
      const r = canvas.getBoundingClientRect();
      const x = e.clientX - r.left - r.width / 2, y = e.clientY - r.top - r.height / 2;
      if (Math.hypot(x, y) < r.width * 0.26) return;
      let a = Math.atan2(y, x) + Math.PI / 2; if (a < 0) a += Math.PI * 2;
      if (loaded !== cur) load();
      const go = () => { audio.currentTime = (a / (Math.PI * 2)) * audio.duration; play(); };
      audio.readyState >= 1 ? go() : audio.addEventListener("loadedmetadata", go, { once: true });
    });

    ["play", "pause"].forEach((ev) => audio.addEventListener(ev, () => { refreshText(); if (!raf) draw(performance.now()); }));
    audio.addEventListener("timeupdate", () => { refreshText(); if (audio.paused) draw(performance.now()); });
    audio.addEventListener("ended", () => { if (cur + 1 < TRACKS.length) toggle(cur + 1); else { loaded = -1; select(0); } });

    addEventListener("resize", resize);
    select(0);
    return { resize };
  })();

  /* ======================================================================
     IV. Discography — the Spotify player loads only when asked for
     (no third-party requests or cookies before that; without JS it is a plain link)
     ====================================================================== */
  (function discography() {
    const albums = $$(".album");
    const shelf = $$(".shelf a");
    if (!albums.length) return;

    // only one Spotify player at a time: switching albums removes it (and stops its sound)
    function closePlayer() {
      $$(".album__player").forEach((frame) => {
        const note = document.createElement("p");
        note.className = "album__note";
        note.textContent = t("disco.note");
        frame.replaceWith(note);
      });
      $$(".album__play.on").forEach((b) => b.classList.remove("on"));
    }

    function show(n, focus) {
      const next = $("#album-" + n);
      if (!next || next.classList.contains("on")) return;
      closePlayer();
      albums.forEach((a) => a.classList.toggle("on", a === next));
      shelf.forEach((a) => (a.dataset.album === String(n) ? a.setAttribute("aria-current", "true") : a.removeAttribute("aria-current")));
      if (focus) {
        const top = next.getBoundingClientRect().top;
        if (top < 0 || top > innerHeight * 0.5) next.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
        $(".album__title", next).focus({ preventScroll: true });
      }
    }

    root.classList.add("disco-js");
    albums.forEach((a) => $(".album__title", a).setAttribute("tabindex", "-1"));
    shelf.forEach((a) => a.addEventListener("click", (e) => { e.preventDefault(); show(a.dataset.album, true); }));

    $$(".album__play[data-spotify]").forEach((btn) => btn.addEventListener("click", (e) => {
      e.preventDefault();
      const body = btn.closest(".album__body");
      let frame = $(".album__player", body);
      if (!frame) {
        frame = document.createElement("iframe");
        frame.className = "album__player";
        frame.src = `https://open.spotify.com/embed/album/${btn.dataset.spotify}?utm_source=generator&theme=0`;
        frame.title = `Spotify — ${$(".album__title", body).textContent}`;
        frame.allow = "autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture";
        frame.loading = "lazy";
        $(".album__note", body).replaceWith(frame);
      }
      $("#player").pause();
      btn.classList.add("on");
      frame.focus();
    }));
  })();

  /* ======================================================================
     V. Gallery — filters + lightbox (tiles are plain links to the large image)
     ====================================================================== */
  (function gallery() {
    const grid = $("#grid");
    const sets = $$(".set", grid);
    const photo = (tile) => ({ name: tile.dataset.name, w: +tile.dataset.w, h: +tile.dataset.h, ext: tile.dataset.ext, tile });
    let visible = $$(".tile", grid).map(photo);

    $$("#filters button").forEach((b) => b.addEventListener("click", () => {
      const s = b.dataset.series;
      $$("#filters button").forEach((x) => x.setAttribute("aria-selected", String(x === b)));
      sets.forEach((set) => {
        set.hidden = !(s === "all" || set.dataset.series === s);
        if (!set.hidden) $$(".tile", set).forEach((tile, k) => {
          tile.classList.remove("enter"); void tile.offsetWidth;
          tile.style.animationDelay = `${Math.min(k, 12) * 0.03}s`;
          tile.classList.add("enter");
        });
      });
      visible = $$(".set:not([hidden]) .tile", grid).map(photo);
      requestAnimationFrame(onScroll);
    }));
    $$("img", grid).forEach((img) => img.complete ? img.classList.add("ok") : img.addEventListener("load", () => img.classList.add("ok"), { once: true }));

    const lb = $("#lightbox"), img = $("#lbImg");
    let idx = 0, opener = null;
    const fit = (w, h, m) => { const k = Math.min(1, m / Math.max(w, h)); return [Math.round(w * k), Math.round(h * k)]; };
    function show(i) {
      idx = (i + visible.length) % visible.length;
      const p = visible[idx];
      const [w, h] = fit(p.w, p.h, 2000);
      img.classList.add("loading");
      img.onload = () => img.classList.remove("loading");
      img.width = w; img.height = h;
      img.src = `${ROOT}assets/photos/lg/${p.name}.webp`;
      img.alt = $("img", p.tile).alt;
      $("#lbCount").textContent = `V — ${pad(idx + 1)} / ${pad(visible.length)}`;
      $("#lbDownload").href = `${ROOT}assets/press/${p.name}.${p.ext}`;
      $("#lbDownload").setAttribute("download", `Monika-Leskovar-${p.name}.${p.ext}`);
      [idx + 1, idx - 1].forEach((n) => { new Image().src = `${ROOT}assets/photos/lg/${visible[(n + visible.length) % visible.length].name}.webp`; });
    }
    function close() { lb.hidden = true; document.body.style.overflow = ""; opener && opener.focus(); }

    grid.addEventListener("click", (e) => {
      const tile = e.target.closest(".tile");
      if (!tile || e.metaKey || e.ctrlKey || e.shiftKey) return;
      e.preventDefault();
      opener = tile;
      lb.hidden = false; document.body.style.overflow = "hidden";
      show(visible.findIndex((p) => p.tile === tile));
      $("#lbClose").focus();
    });
    $("#lbClose").addEventListener("click", close);
    $("#lbPrev").addEventListener("click", () => show(idx - 1));
    $("#lbNext").addEventListener("click", () => show(idx + 1));
    $(".lb__stage").addEventListener("click", (e) => { if (e.target === e.currentTarget) close(); });
    addEventListener("keydown", (e) => {
      if (e.key === "Escape") closeMenu();
      if (lb.hidden) return;
      if (e.key === "Escape") close();
      if (e.key === "ArrowRight") show(idx + 1);
      if (e.key === "ArrowLeft") show(idx - 1);
      if (e.key === "Tab") {
        const f = $$("button, a", lb);
        if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
        else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
      }
    });
    let sx = null;
    lb.addEventListener("touchstart", (e) => { sx = e.touches[0].clientX; }, { passive: true });
    lb.addEventListener("touchend", (e) => {
      if (sx === null) return;
      const dx = e.changedTouches[0].clientX - sx;
      if (Math.abs(dx) > 50) show(idx + (dx < 0 ? 1 : -1));
      sx = null;
    });
  })();

  /* ======================================================================
     Accordatura — cello tuner
     Reference tones are synthesised; the microphone is analysed locally
     (McLeod pitch method). The strings swell at the real beat rate
     |f − target|, so they calm down as the string comes into tune.
     ====================================================================== */
  (() => {
    const dlg = $("#tuner");
    if (!dlg) return;
    const canvas = $("#tuCanvas"), ctx = canvas.getContext("2d");
    const keys = $$("#tuKeys button");
    const NOTES = t("tuner.notes");
    const ROMAN = ["IV", "III", "II", "I"];
    const LETTER = ["C", "G", "D", "A"];
    const OCT = [2, 2, 3, 3];
    const fmt = (n, d) => n.toLocaleString(lang, { minimumFractionDigits: d, maximumFractionDigits: d });

    let ref = Math.max(415, Math.min(446, parseInt(read("tunerA"), 10) || 442));
    let pure = read("tunerFifths") !== "tempered";
    let ac = null, stream = null, analyser = null, buf = null, raf = 0, opener = null;
    let tone = null, toneString = -1;
    let freq = 0, cents = 0, shown = 0, beat = 0, active = -1, lastHit = 0;
    const hist = [];

    // A3 = ref / 2; the lower strings are a fifth apart, pure (3:2) or equal-tempered
    function targets() {
      const a = ref / 2, k = pure ? 2 / 3 : Math.pow(2, -7 / 12);
      return [a * k * k * k, a * k * k, a * k, a];
    }

    function showRef() {
      $("#tuRef").textContent = ref;
      $$("[data-tuner-a]").forEach((b) => { b.textContent = ref; });
      $("#tuFifthsVal").textContent = t(pure ? "tuner.pure" : "tuner.tempered");
      $("#tuFifths").setAttribute("aria-pressed", String(pure));
      if (tone) { tone.osc.frequency.setTargetAtTime(targets()[toneString], ac.currentTime, 0.02); if (!freq) showString(toneString); }
    }

    function audioCtx() {
      if (!ac) ac = new (window.AudioContext || window.webkitAudioContext)();
      if (ac.state === "suspended") ac.resume();
      return ac;
    }
    const quiet = () => { const p = $("#player"); if (p && !p.paused) p.pause(); };
    const status = (s) => { $("#tuStatus").textContent = s; };

    /* ---- reference tone: a soft bowed-string timbre ---- */
    let wave = null;
    function play(i) {
      const was = toneString;
      stopTone();
      if (was === i) return;
      const c = audioCtx();
      quiet();
      if (!wave) {
        const h = [0, 1, .62, .48, .36, .3, .22, .17, .13, .1, .08, .06, .05, .04];
        wave = c.createPeriodicWave(new Float32Array(h.length), Float32Array.from(h));
      }
      const osc = c.createOscillator(), lp = c.createBiquadFilter(), g = c.createGain(), now = c.currentTime;
      osc.setPeriodicWave(wave);
      osc.frequency.value = targets()[i];
      lp.type = "lowpass"; lp.frequency.value = 2200; lp.Q.value = .5;
      g.gain.setValueAtTime(0, now);
      g.gain.linearRampToValueAtTime(.16, now + .35);
      g.gain.setValueAtTime(.16, now + 3.2);
      g.gain.linearRampToValueAtTime(0, now + 4.2);
      osc.connect(lp).connect(g).connect(c.destination);
      osc.start(now); osc.stop(now + 4.3);
      tone = { osc, g };
      toneString = i;
      if (!freq) showString(i);
      osc.onended = () => { if (tone && tone.osc === osc) { tone = null; toneString = -1; paintKeys(); if (!freq) reset(); } };
      paintKeys();
      loop();
    }
    function stopTone() {
      if (!tone) return;
      const now = ac.currentTime;
      tone.g.gain.cancelScheduledValues(now);
      tone.g.gain.setTargetAtTime(0, now, .06);
      tone.osc.stop(now + .3);
      tone = null; toneString = -1;
      paintKeys();
      if (!freq) reset();
    }
    // while a reference tone sounds (and the microphone hears nothing), name it
    function showString(i) {
      dlg.classList.add("ref");
      $("#tuNote").textContent = LETTER[i];
      $("#tuNum").textContent = `${t("tuner.string")} ${ROMAN[i]} · ${LETTER[i]}${OCT[i]}`;
      $("#tuCents").textContent = `${fmt(targets()[i], 1)} Hz`;
    }
    function paintKeys() {
      keys.forEach((k, i) => {
        k.classList.toggle("on", i === toneString);
        k.classList.toggle("hit", i === active && i !== toneString);
      });
    }

    /* ---- microphone ---- */
    async function micOn() {
      const c = audioCtx();
      quiet();
      try {
        stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false } });
      } catch (e) {
        status(t("tuner.denied"));
        return;
      }
      if (dlg.hidden) { stream.getTracks().forEach((tr) => tr.stop()); stream = null; return; }
      analyser = c.createAnalyser();
      analyser.fftSize = 4096;
      buf = new Float32Array(analyser.fftSize);
      c.createMediaStreamSource(stream).connect(analyser);
      $("#tuMic").setAttribute("aria-pressed", "true");
      $("#tuMicLabel").textContent = t("tuner.micOff");
      status(t("tuner.listen"));
      loop();
    }
    function micOff() {
      if (stream) stream.getTracks().forEach((tr) => tr.stop());
      stream = null; analyser = null;
      $("#tuMic").setAttribute("aria-pressed", "false");
      $("#tuMicLabel").textContent = t("tuner.mic");
      status(t("tuner.idle"));
      reset();
    }

    // McLeod pitch method on a 2× decimated frame (the low C at 65 Hz needs a long window)
    const half = new Float32Array(2048), nsdf = new Float32Array(1001);
    function detect() {
      analyser.getFloatTimeDomainData(buf);
      let rms = 0;
      for (let i = 0; i < 2048; i++) { const v = (buf[2 * i] + buf[2 * i + 1]) / 2; half[i] = v; rms += v * v; }
      if (Math.sqrt(rms / 2048) < .006) return 0;
      const sr = ac.sampleRate / 2, maxT = Math.min(1000, Math.ceil(sr / 55)), minT = Math.floor(sr / 1100), W = 2048 - maxT;
      for (let tau = minT; tau <= maxT; tau++) {
        let acf = 0, m = 0;
        for (let i = 0; i < W; i++) { const a = half[i], b = half[i + tau]; acf += a * b; m += a * a + b * b; }
        nsdf[tau] = m ? 2 * acf / m : 0;
      }
      // key maxima: the highest point of every positive lobe after the first zero crossing
      const peaks = [];
      let tau = minT;
      while (tau < maxT && nsdf[tau] > 0) tau++;
      while (tau < maxT) {
        while (tau < maxT && nsdf[tau] <= 0) tau++;
        let best = tau;
        while (tau < maxT && nsdf[tau] > 0) { if (nsdf[tau] > nsdf[best]) best = tau; tau++; }
        if (best < maxT && nsdf[best] > 0) peaks.push(best);
      }
      if (!peaks.length) return 0;
      const top = Math.max(...peaks.map((p) => nsdf[p]));
      if (top < .8) return 0;
      const p = peaks.find((q) => nsdf[q] >= top * .9);
      const a = nsdf[p - 1], b = nsdf[p], c = nsdf[p + 1], d = a - 2 * b + c;
      return sr / (p + (d ? (a - c) / (2 * d) : 0));
    }

    function reset() {
      hist.length = 0; freq = 0; active = -1;
      dlg.classList.remove("live", "near", "tuned", "ref");
      $("#tuNote").textContent = "—";
      $("#tuNum").innerHTML = "&nbsp;";
      $("#tuCents").innerHTML = "&nbsp;";
      if (toneString >= 0) showString(toneString);
      paintKeys();
    }

    function listen() {
      const f = detect(), now = performance.now();
      if (f) {
        hist.push(f); if (hist.length > 5) hist.shift();
        freq = [...hist].sort((x, y) => x - y)[hist.length >> 1];
        lastHit = now;
      } else {
        if (freq && now - lastHit > 700) reset();
        return;
      }

      const T = targets();
      const dev = T.map((x) => 1200 * Math.log2(freq / x));
      let s = dev.reduce((bi, v, i) => Math.abs(v) < Math.abs(dev[bi]) ? i : bi, 0);
      let name, num, target;
      if (Math.abs(dev[s]) <= 150) {
        cents = dev[s]; target = T[s];
        name = LETTER[s]; num = `${t("tuner.string")} ${ROMAN[s]} · ${LETTER[s]}${OCT[s]}`;
      } else {
        // not an open string: show the nearest chromatic note
        s = -1;
        const n = 12 * Math.log2(freq / ref) + 57, r = Math.round(n);
        cents = (n - r) * 100; target = freq / Math.pow(2, cents / 1200);
        name = NOTES[((r % 12) + 12) % 12]; num = `${name}${Math.floor(r / 12)}`;
      }
      if (s !== active || !dlg.classList.contains("live")) shown = cents;
      active = s;
      shown += (cents - shown) * .35;
      beat = Math.abs(freq - target);
      const c = Math.round(shown), ok = Math.abs(shown) < 3;
      dlg.classList.remove("ref");
      dlg.classList.add("live");
      dlg.classList.toggle("tuned", ok);
      dlg.classList.toggle("near", !ok && Math.abs(shown) < 12);
      $("#tuNote").textContent = name;
      $("#tuNum").textContent = num;
      $("#tuCents").textContent = `${ok ? t("tuner.inTune") : (c > 0 ? "+" : c < 0 ? "−" : "±") + Math.abs(c) + " ¢"}  ·  ${fmt(freq, 1)} Hz`;
      $("#tuNeedle").style.transform = `translateX(${(Math.max(-50, Math.min(50, shown)) / 100 * $(".tu__gauge").clientWidth).toFixed(1)}px)`;
      paintKeys();
    }

    /* ---- the four strings ---- */
    let W = 0, H = 0, dpr = 1;
    const amp = [0, 0, 0, 0];
    function size() {
      dpr = Math.min(2, devicePixelRatio || 1);
      W = canvas.clientWidth; H = canvas.clientHeight;
      canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    }
    function draw(now) {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);
      const ts = now / 1000, tuned = dlg.classList.contains("tuned");
      for (let i = 0; i < 4; i++) {
        const x = W * (i + .5) / 4, thick = 2.6 - i * .45;
        const sounding = i === toneString || (i === active && freq > 0);
        amp[i] += ((sounding ? 1 : 0) - amp[i]) * .12;
        let a = amp[i] * Math.min(W / 16, 14);
        if (!reduce && i === active && freq && !tuned) a *= .45 + .55 * Math.abs(Math.cos(Math.PI * Math.min(8, beat) * ts));
        const hot = i === toneString || (i === active && tuned);
        if (a > .2) {
          // a bowed string blurs into a lens; its width is the vibration amplitude
          ctx.beginPath();
          for (let k = 0; k <= 40; k++) ctx.lineTo(x + a * Math.sin(Math.PI * k / 40), H * k / 40);
          for (let k = 40; k >= 0; k--) ctx.lineTo(x - a * Math.sin(Math.PI * k / 40), H * k / 40);
          ctx.fillStyle = hot ? "rgba(234,174,110,.22)" : "rgba(236,233,226,.1)";
          ctx.fill();
          if (!reduce) {
            const w = Math.sin(ts * 47 + i) * a;
            ctx.beginPath();
            for (let k = 0; k <= 40; k++) ctx.lineTo(x + w * Math.sin(Math.PI * k / 40), H * k / 40);
            ctx.strokeStyle = hot ? "rgba(234,174,110,.55)" : "rgba(236,233,226,.35)";
            ctx.lineWidth = thick * .7; ctx.stroke();
          }
        }
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H);
        ctx.strokeStyle = hot ? "#eaae6e" : amp[i] > .05 ? "rgba(236,233,226,.75)" : "rgba(236,233,226,.32)";
        ctx.lineWidth = thick; ctx.stroke();
      }
    }
    function loop() {
      if (raf) return;
      const step = (now) => {
        raf = 0;
        if (dlg.hidden) return;
        if (analyser) listen();
        draw(now);
        if (analyser || tone || amp.some((v) => v > .01)) raf = requestAnimationFrame(step);
      };
      raf = requestAnimationFrame(step);
    }

    /* ---- open / close ---- */
    function open(from) {
      opener = from || null;
      closeMenu();
      dlg.hidden = false;
      document.body.style.overflow = "hidden";
      requestAnimationFrame(() => { dlg.classList.add("open"); size(); draw(performance.now()); });
      $("#tuClose").focus();
    }
    function close() {
      stopTone(); micOff();
      dlg.classList.remove("open");
      document.body.style.overflow = "";
      setTimeout(() => { if (!dlg.classList.contains("open")) dlg.hidden = true; }, reduce ? 0 : 800);
      if (ac) ac.suspend();
      if (location.hash === "#accordatura") history.replaceState(null, "", location.pathname + location.search);
      if (opener) opener.focus();
    }

    $$("[data-tuner]").forEach((b) => b.addEventListener("click", () => open(b)));
    $("#tuClose").addEventListener("click", close);
    keys.forEach((k, i) => k.addEventListener("click", () => play(i)));
    $("#tuMic").addEventListener("click", () => {
      if (stream) { micOff(); return; }
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { status(t("tuner.denied")); return; }
      micOn();
    });
    const nudge = (d) => { ref = Math.max(415, Math.min(446, ref + d)); store("tunerA", ref); showRef(); };
    $("#tuDown").addEventListener("click", () => nudge(-1));
    $("#tuUp").addEventListener("click", () => nudge(1));
    $("#tuFifths").addEventListener("click", () => { pure = !pure; store("tunerFifths", pure ? "pure" : "tempered"); showRef(); });
    addEventListener("resize", () => { if (!dlg.hidden) { size(); draw(performance.now()); } });
    addEventListener("keydown", (e) => {
      if (dlg.hidden) return;
      if (e.key === "Escape") close();
      if (e.key === "Tab") {
        const f = $$("button", dlg);
        if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
        else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
      }
    });
    document.addEventListener("visibilitychange", () => { if (document.hidden && !dlg.hidden) { stopTone(); if (stream) micOff(); } });

    showRef();
    // a shareable link straight to the tuner: …/#accordatura
    if (location.hash === "#accordatura") setTimeout(() => open(), root.classList.contains("no-intro") ? 0 : 2200);
  })();

  /* ======================================================================
     Cursor (fine pointers only)
     ====================================================================== */
  if (matchMedia("(hover: hover) and (pointer: fine)").matches && !reduce) {
    const cur = $("#cursor"), label = $("#cursorLabel");
    let x = innerWidth / 2, y = innerHeight / 2, cx = x, cy = y;
    addEventListener("pointermove", (e) => { x = e.clientX; y = e.clientY; }, { passive: true });
    const loop = () => {
      cx += (x - cx) * 0.2; cy += (y - cy) * 0.2;
      cur.style.transform = `translate3d(${cx}px, ${cy}px, 0)`;
      requestAnimationFrame(loop);
    };
    loop();
    document.addEventListener("pointerover", (e) => {
      const big = e.target.closest("[data-cursor]");
      const link = !big && e.target.closest("a, button, canvas");
      cur.classList.toggle("big", !!big);
      cur.classList.toggle("link", !!link);
      if (big) label.textContent = t(`cursor.${big.dataset.cursor}`);
    });
    document.addEventListener("pointerleave", () => cur.classList.remove("big", "link"));
  }

  /* ======================================================================
     Scroll-driven bits
     ====================================================================== */
  const heroMedia = $("#heroMedia");
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } }), { rootMargin: "0px 0px -10% 0px" });
  ["shead", "tracklist", "disc", "albums", "filters", "concerts__cols", "coda__title", "coda__mail", "coda__social", "with", "bio__more"]
    .forEach((c) => $$("." + c).forEach((el) => { el.classList.add("rv"); io.observe(el); }));

  let ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      const y = scrollY;
      head.classList.toggle("scrolled", y > 30);
      head.classList.toggle("hide", y > lastY && y > innerHeight && !document.body.classList.contains("menu-open"));
      lastY = y;
      if (!reduce && y < innerHeight * 1.2) heroMedia.style.transform = `translate3d(0, ${(y * 0.28).toFixed(1)}px, 0)`;
      let active = -1;
      targets.forEach((s, i) => { if (s && s.getBoundingClientRect().top < innerHeight * 0.45) active = i; });
      navLinks.forEach((a, i) => a.classList.toggle("active", i === active));
      updateStatement();
      updateTimeline();
    });
  }

  /* ======================================================================
     Init
     ====================================================================== */
  sizeTimeline();
  Disc.resize();
  onScroll();
  addEventListener("scroll", onScroll, { passive: true });
  addEventListener("resize", () => { sizeTimeline(); onScroll(); });

  const fontsReady = document.fonts ? Promise.race([document.fonts.ready, new Promise((r) => setTimeout(r, 1200))]) : Promise.resolve();
  runIntro(() => fontsReady.then(() => {
    sizeTimeline();
    Disc.resize();
    root.classList.add("ready");
    onScroll();
  }));
})();
